import{_ as e,o as i,c as a,a2 as s}from"./chunks/framework.hwbV7reR.js";const k=JSON.parse('{"title":"TrustTunnel: проверка транспорта","description":"","frontmatter":{},"headers":[],"relativePath":"trusttunnel.md","filePath":"trusttunnel.md","lastUpdated":null}'),d={name:"trusttunnel.md"};function n(o,t,r,l,c,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="trusttunnel-проверка-транспорта" tabindex="-1">TrustTunnel: проверка транспорта <a class="header-anchor" href="#trusttunnel-проверка-транспорта" aria-label="Permalink to &quot;TrustTunnel: проверка транспорта&quot;">​</a></h1><p>Статус: транспорт проверен на реальном узле; экспериментальный NodeDriver реализован против проекта API нашего агента. Сам агент ещё не реализован и не прошёл испытания жизненного цикла. Production capabilities по-прежнему объявляют только AmneziaWG. Клиенты Undercore пока не включают движок TrustTunnel.</p><h2 id="проверенные-версии-и-источники" tabindex="-1">Проверенные версии и источники <a class="header-anchor" href="#проверенные-версии-и-источники" aria-label="Permalink to &quot;Проверенные версии и источники&quot;">​</a></h2><ul><li>Endpoint <strong>1.1.0</strong>, commit <code>fab5b8353a19332f935fa30869307d37d4a898d1</code>: <a href="https://github.com/TrustTunnel/TrustTunnel/tree/v1.1.0" target="_blank" rel="noreferrer">исходники</a>, <a href="https://github.com/TrustTunnel/TrustTunnel/blob/v1.1.0/CONFIGURATION.md" target="_blank" rel="noreferrer">настройки</a>.</li><li>CLI <strong>1.1.11</strong>: <a href="https://github.com/TrustTunnel/TrustTunnelClient/blob/v1.1.11/trusttunnel/README.md" target="_blank" rel="noreferrer">документация клиента</a>.</li><li>Подписи официальных бинарников проверяются по <a href="https://github.com/TrustTunnel/TrustTunnel/blob/v1.1.0/VERIFY_RELEASES.md" target="_blank" rel="noreferrer">инструкции upstream</a>. Фиксируйте конкретную версию и SHA256 проверенного бинарника; SHA256 сам по себе не доказывает автора файла.</li></ul><p>Результаты относятся к указанным версиям. Документация ветки master может описывать возможности, отсутствующие в опубликованном endpoint.</p><h2 id="результаты-сетевого-испытания" tabindex="-1">Результаты сетевого испытания <a class="header-anchor" href="#результаты-сетевого-испытания" aria-label="Permalink to &quot;Результаты сетевого испытания&quot;">​</a></h2><p>11 октября 2026 года проверен отдельный Linux endpoint и официальный macOS CLI. Клиент работал через локальный SOCKS; системные VPN, маршруты и DNS Mac не менялись.</p><table tabindex="0"><thead><tr><th>Проверка</th><th>Результат</th></tr></thead><tbody><tr><td>HTTPS через HTTP/2</td><td>Проходит</td></tr><tr><td>HTTPS через HTTP/3 / QUIC</td><td>Проходит</td></tr><tr><td>Внешний IP</td><td>Соответствует явно назначенному выходу стенда</td></tr><tr><td>Неверный закреплённый TLS-сертификат</td><td>Соединение отклонено обоими транспортами</td></tr><tr><td>Новый пароль в credentials.toml + SIGHUP</td><td>Старый работает, новый отклоняется</td></tr><tr><td>Полный restart endpoint после смены пароля</td><td>Старый отклоняется, новый работает</td></tr></tbody></table><p>Это не измерение пропускной способности, устойчивости к блокировкам или проверка NetworkExtension. Производственные назначения и действующие VPN-узлы не переключались.</p><h2 id="адаптер-конфигурации" tabindex="-1">Адаптер конфигурации <a class="header-anchor" href="#адаптер-конфигурации" aria-label="Permalink to &quot;Адаптер конфигурации&quot;">​</a></h2><p><code>orchestrator/infrastructure/drivers/trusttunnel_configuration.py</code> проверяет официальный TOML-экспорт и возвращает <code>TransportConfiguration</code> с форматом <code>trusttunnel-toml</code>. Пока документ содержит секцию <code>[endpoint]</code>; политику маршрутов и listener добавляет клиентский backend. Адаптер не создаёт доступ и не реализует NodeDriver, поэтому не зарегистрирован в bootstrap.</p><ul><li>Проверка TLS обязательна; <code>skip_verification=true</code> отклоняется.</li><li>Имена полей, типы, размер, адреса и PEM проверяются до передачи клиенту.</li><li>Учётные данные скрыты в repr и ошибках, конфигурация остаётся в памяти.</li><li>Параметры <code>custom_sni</code> и <code>client_random_prefix</code> пока принимаются только пустыми: дополнительные режимы должны получить отдельные испытания.</li><li>Поддержка IPv6 берётся из фактических возможностей узла. Endpoint 1.1.0 при экспорте ставит <code>has_ipv6=true</code> независимо от своей настройки; адаптер не наследует это обещание автоматически.</li></ul><p>Экспорты <code>.conf</code>, <code>.vpn</code> и QR Amnezia не переносятся на TrustTunnel. Upstream умеет собственный TOML и <code>tt://</code> deep link; их включение в публичный API оркестратора требует отдельного согласованного контракта и испытаний клиентов.</p><h2 id="воспроизводимая-проверка" tabindex="-1">Воспроизводимая проверка <a class="header-anchor" href="#воспроизводимая-проверка" aria-label="Permalink to &quot;Воспроизводимая проверка&quot;">​</a></h2><p>На подготовленном узле экспортируйте параметры в приватный файл, не в терминал:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">umask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 077</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trusttunnel_endpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hosts.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_ENDPOINT_IP:9443</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> endpoint.toml</span></span></code></pre></div><p>Параметр <code>--format toml</code> обязателен: по умолчанию endpoint 1.1.0 печатает deep link. Передайте файл на машину оператора по защищённому каналу, сохраните права 0600. После проверки подписи официального клиентского бинарника:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/probe_trusttunnel.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/trusttunnel_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --sha256</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VERIFIED_BINARY_SHA256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --endpoint-export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/endpoint.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --expected-egress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EXPECTED_PUBLIC_IP</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http2</span></span></code></pre></div><p>Повторите с <code>--transport http3</code>. Проверка выполняет запросы к api.ipify.org и example.com через отдельный SOCKS на loopback; не требует root, не создаёт TUN, не настраивает системный proxy и не меняет системный VPN. Адрес выхода должен совпасть с ожидаемым. Временный профиль удаляется, дочерний клиент завершается; вывод содержит только результаты и длительности, без паролей и тел страниц. Закройте endpoint и удалите тестовый доступ после испытания.</p><h2 id="что-требуется-узловому-агенту" tabindex="-1">Что требуется узловому агенту <a class="header-anchor" href="#что-требуется-узловому-агенту" aria-label="Permalink to &quot;Что требуется узловому агенту&quot;">​</a></h2><p>У штатного endpoint 1.1.0 нет проверенного API жизненного цикла наших назначений. Пользователи находятся в файле, а authenticator загружает их в память при старте. SIGHUP обновляет TLS hosts, но не credentials. Простая запись файла с последующим SIGHUP не подтверждает ни выдачу, ни отзыв. Перезапуск общего процесса прерывает подключения его пользователей, поэтому не подходит как обычная операция выдачи.</p><p>До включения экспериментального драйвера нужны:</p><ol><li>Версионированный аутентифицированный API агента и стабильный server_id.</li><li>Узловой журнал binding_key/remote_id, идемпотентные создание и мутации; восстановление прежнего результата после потери ответа или рестарта агента.</li><li>Применение изменений к работающему runtime с подтверждением. Для revoke — прекращение существующих сессий и отказ новым. Для создания одного доступа — сохранение сессий остальных клиентов.</li><li>Локальное исполнение срока доступа даже при недоступном оркестраторе; поведение при отказе агента и скачке времени должно быть определено и проверено.</li><li>Согласованная выдача параметров с состоянием доступа, без секретов в логах.</li><li>Прохождение общей матрицы драйверов, затем стендовые проверки отказов.</li></ol><p>Нельзя выставлять <code>enforces_expiry</code>/<code>confirmed_revoke</code> только на основании работы туннеля или успешной записи файла. DriverRegistry отвергает такую реализацию. Lease и аварийное переключение добавляются лишь после независимого механизма прекращения доступа на узле. На первом этапе TrustTunnel выбирается явно; автоматическая межпротокольная миграция не входит в этот прототип.</p><p>Предпочтительное следующее исследование — небольшой управляющий слой над официальной библиотекой TrustTunnel: динамическая авторизация и управление сессиями. Перед реализацией нужно проверить необходимые точки расширения, чтобы не обещать подтверждённый отзыв там, где библиотека его не предоставляет.</p><h2 id="адаптер-управляющего-api" tabindex="-1">Адаптер управляющего API <a class="header-anchor" href="#адаптер-управляющего-api" aria-label="Permalink to &quot;Адаптер управляющего API&quot;">​</a></h2><p><code>trusttunnel.py</code> реализует порт <code>NodeDriver</code>, <code>trusttunnel_contract.py</code> описывает проект API <strong>нашего агента</strong>. Это не API штатного TrustTunnel endpoint. <code>node_http.py</code> содержит общий HTTPS-транспорт с таймаутами, ограниченным пулом, пределом размера ответа и безопасными ошибками; Amnezia использует тот же транспорт. Протокольные проверки остаются в отдельных адаптерах.</p><p>JSON Schema запросов и ответов: <code>contracts/trusttunnel-agent.schema.json</code>. Проверка <code>scripts/check_contracts.py</code> обнаруживает расхождение схемы и моделей. Контракт пока экспериментальный и может измениться вместе с реализацией агента. Входящий API backend и схема SQLite этим этапом не меняются.</p><p>Все запросы идут по HTTPS со служебным Bearer-токеном узла. Ответ 200 обязан иметь <code>Cache-Control: no-store</code> и общую оболочку: <code>schema_version: 1</code>, <code>server_id</code>, <code>protocol: &quot;trusttunnel&quot;</code>, <code>status: &quot;ok&quot;</code>. Каждый ответ сверяется с ожидаемым узлом. Перед операцией адаптер проверяет health и обязательные гарантии агента. Управляющий API и адрес VPN-туннеля — разные адреса/порты.</p><table tabindex="0"><thead><tr><th>Метод</th><th>Путь</th><th>Запрос / ответ</th></tr></thead><tbody><tr><td>GET</td><td><code>/v1/health</code></td><td><code>Health</code>: идентичность и три гарантии lifecycle</td></tr><tr><td>GET</td><td><code>/v1/clients</code></td><td><code>ClientList</code>: полный список, максимум 10 000 записей; дубли запрещены</td></tr><tr><td>POST</td><td><code>/v1/clients</code></td><td><code>Create</code> → <code>ClientSnapshot</code></td></tr><tr><td>GET</td><td><code>/v1/clients/{id}</code></td><td><code>ClientSnapshot</code></td></tr><tr><td>POST</td><td><code>/v1/clients/{id}/renew</code></td><td><code>Renewal</code> → <code>ClientSnapshot</code></td></tr><tr><td>POST</td><td><code>/v1/clients/{id}/disable</code></td><td><code>{}</code> → подтверждённый disabled/expired</td></tr><tr><td>POST</td><td><code>/v1/clients/{id}/enable</code></td><td><code>{}</code> → подтверждённый active</td></tr><tr><td>POST</td><td><code>/v1/clients/{id}/replace</code></td><td><code>Replacement</code> → <code>ClientSnapshot</code></td></tr><tr><td>GET</td><td><code>/v1/clients/{id}/connection</code></td><td><code>ConnectionSnapshot</code>: состояние и параметры одним снимком</td></tr></tbody></table><p>Создание передаёт <code>external_id</code> (binding_key), <code>name</code>, <code>expires_at</code> в UTC с миллисекундами. Агент назначает <code>client_id</code> формата <code>ttapi_</code> + 32 hex-символа. Канонический device_id, пользователи и биллинг остаются за этой границей. Повтор того же binding должен вернуть тот же ID; другой срок при повторе create — 409, продление выполняется отдельной операцией. Агент сохраняет идемпотентность после перезапуска. Адаптер не генерирует новые ключи и не повторяет мутации сам.</p><p>Продление и замена передают <code>expires_at</code> и <code>idempotency_key</code>; замена также <code>expected_external_id</code> и <code>allow_create</code>. В этом контракте замена обновляет учётные данные под прежними client_id/binding: старые данные и сессии должны быть отозваны до подтверждения. При <code>allow_create: false</code> отсутствующий runtime-доступ не создаётся заново; агент возвращает конфликт. Повтор завершённой операции возвращает её результат, не выполняет повторную ротацию.</p><p>Снимок клиента содержит ID, binding, имя, срок, status (active/disabled/expired), created_at, updated_at. <code>applied: true</code> означает, что состояние подтверждено VPN-runtime, а не только записано в базу. Для disable это включает разрыв текущих сессий и отказ новых. Ответ active на disable или <code>applied: false</code> адаптер отклоняет. Срок продления и идентичность ответа должны совпадать с запросом.</p><p>ConnectionSnapshot дополнительно содержит <code>endpoint_export</code> (официальный плоский TOML, максимум 64 KiB), <code>ipv6_available</code> и <code>transport</code> (http2/http3). Username экспорта равен client_id; пароль задаёт и хранит агент. Адаптер проверяет binding, активность, срок, соответствие username и обязательность TLS, затем возвращает документ <code>[endpoint]</code>. Текст документа скрыт в repr и ошибках.</p><p>404, 409, 410 и 422 сохраняют HTTP-смысл, тело ошибки агента наружу не передаётся. 401/403, перенаправление, 405, 429, 5xx и невалидный ответ не запускают fallback; таймаут оставляет исход неизвестным. Повтор выполняется с тем же binding/ключом. Для недоступного доступа выдача конфигурации возвращает 410 <code>access_unavailable</code>.</p><p><strong>Ограничение этапа:</strong> флаги lifecycle у адаптера оставлены выключенными, DriverRegistry отвергает его, bootstrap его не регистрирует. Объявление гарантий в health не является доказательством их исполнения. HTTP-тесты проверяют только поведение адаптера: неизменность повторных запросов, отбрасывание ошибочных ответов, защиту секретов и границы протоколов. Общая матрица с реальным агентом и испытания истечения срока/разрыва сессий ещё нужны. Leases, файлы, deep link и QR не включены.</p>`,36)])])}const u=e(d,[["render",n]]);export{k as __pageData,u as default};
